// 批次一 P3/P4 接线回归（dist + package.json 冒烟）：
//  - 命令注册与守卫（autoGenerated / 构建中 / 只读 / 编辑器占用先关）
//  - .cbp 文本手术接线、两段式改名回退、跨工程引用仅提示
//  - 虚拟文件夹三命令 + 删除确认（“不删磁盘文件”）+ 拖拽回调接线
//  - package.json 命令/菜单 when 与 menuStructure 静态项
const fs = require('fs');
const path = require('path');

let pass = 0, fail = 0;
function check(name, cond, got, want) {
  if (cond) { pass++; console.log('OK   ' + name); }
  else { fail++; console.log('FAIL ' + name + '  got=' + JSON.stringify(got) + ' want=' + JSON.stringify(want)); }
}

const ext = fs.readFileSync(path.resolve(__dirname, '../dist/extension.js'), 'utf-8');
const prov = fs.readFileSync(path.resolve(__dirname, '../dist/ui/projectTreeProvider.js'), 'utf-8');
const menu = fs.readFileSync(path.resolve(__dirname, '../dist/ui/menuStructure.js'), 'utf-8');
const pkg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../package.json'), 'utf-8'));

// ---- 1. P3 重命名 ----
check('命令注册 codeblocks.renameFile → renameProjectFile',
  /codeblocks\.renameFile/.test(ext) && /await renameProjectFile\(project, file\)/.test(ext), 'wiring', 'ok');
check('守卫：自动生成文件拒绝（对齐 AutoGeneratedBy）',
  /file\.autoGeneratedBy/.test(ext) && /不能重命名自动生成的文件/.test(ext), 'guard', 'ok');
check('守卫：构建进行中拒绝', /构建进行中，请先停止或等待构建结束后再重命名文件/.test(ext), 'guard', 'ok');
check('守卫：只读文件拒绝（accessSync W_OK）', /accessSync\(abs, fs\.constants\.W_OK\)/.test(ext), 'guard', 'ok');
check('编辑器占用：确认后保存并关闭对应 Tab（TabInputText + tabGroups.close）',
  /该文件已在编辑器中打开/.test(ext) && /vscode\.TabInputText/.test(ext) && /tabGroups\.close/.test(ext), 'editors', 'ok');
check('大小写仅变体/占用：两段式改名回退（临时名 .cb-rename-）',
  /caseOnly/.test(ext) && /cb-rename-/.test(ext), 'fallback', 'ok');
check('文本手术接线：renameUnitInCbpText 且未命中时提示手动修正',
  /renameUnitInCbpText\)\?\(raw, oldRel, newRel\)|renameUnitInCbpText\)\(raw, oldRel, newRel\)/.test(ext)
  && /未能在 \.cbp 中更新引用/.test(ext), 'text-surgery', 'ok');
check('跨工程引用：仅状态栏提示，不自动修改',
  /其它.*个已打开工程引用了该文件/.test(ext), 'notify', 'ok');
check('改名后重解析刷新并打开新文件', /showTextDocument\(vscode\.Uri\.file\(newAbs\)/.test(ext), 'refresh', 'ok');

// ---- 2. P4 虚拟文件夹 ----
check('命令注册：new/rename/delete 三个虚拟文件夹命令',
  /codeblocks\.newVirtualFolder/.test(ext) && /codeblocks\.renameVirtualFolder/.test(ext)
  && /codeblocks\.deleteVirtualFolder/.test(ext), 'commands', 'ok');
check('新建/改名使用输入框校验（validateVirtualFolderPath）',
  (ext.match(/validateVirtualFolderPath/g) || []).length >= 2, 'validate', '>=2');
check('删除：模态确认 + 明确「磁盘文件不会被删除」（只动模型）',
  /模块确认|modal: true/.test(ext) && /磁盘文件不会被删除/.test(ext), 'confirm', 'ok');
check('删除：先统计受影响文件数（countFilesUnderVirtualFolder）',
  /countFilesUnderVirtualFolder\)\(project, folder\)/.test(ext), 'count', 'ok');
check('写回：三命令与拖拽均走 persistProjectAndReload',
  (ext.match(/persistProjectAndReload\(project\)/g) || []).length >= 3, 'persist', '>=3');

// ---- 3. 拖拽（provider） ----
check('拖拽载荷结构化（project / files 两类）',
  /type: 'project'/.test(prov) && /type: 'files'/.test(prov), 'payload', 'ok');
check('文件拖拽：仅同工程、目标限 工程/目录/虚拟文件夹（fileGroup 拒绝）',
  /it\.project !== target\.project\.filename/.test(prov)
  && /target\.kind !== 'folder'/.test(prov) && /target\.kind !== 'virtualFolder'/.test(prov), 'rules', 'ok');
check('拖到工程根 = 清空归属（folder 为空串）', /target\.kind === 'project' \? '' : \(target\.dirKey/.test(prov), 'root', 'ok');
check('DnD 回调接线（onAssignVirtualFolder → 模型 + 写回）',
  /onAssignVirtualFolder = async \(files, folder\)/.test(ext) && /assignFileToVirtualFolder\)\(file, folder\)/.test(ext), 'hook', 'ok');

// ---- 4. package.json / menuStructure ----
const cmd = (id) => (pkg.contributes.commands || []).find((c) => c.command === id);
check('命令贡献：P3/P4 三个命令 + renameFile',
  cmd('codeblocks.renameFile')?.title === 'Rename File...'
  && cmd('codeblocks.newVirtualFolder')?.title === 'Add New Virtual Folder...'
  && cmd('codeblocks.renameVirtualFolder')?.title === 'Rename Virtual Folder...'
  && cmd('codeblocks.deleteVirtualFolder')?.title === 'Delete Virtual Folder',
  ['renameFile', 'newVirtualFolder', 'renameVirtualFolder', 'deleteVirtualFolder'].map((k) => cmd('codeblocks.' + k)?.title), 'ok');
const items = (pkg.contributes.menus || {})['view/item/context'] || [];
const has = (commandName, whenPat) => items.some((m) => m.command === commandName && whenPat.test(m.when));
check('右键菜单：renameFile 属文件族（group 1_file@5）',
  items.some((m) => m.command === 'codeblocks.renameFile' && m.group === '1_file@5' && /viewItem =~ \/\^file\//.test(m.when)), 'menu', 'ok');
check('右键菜单：虚拟文件夹三命令挂 virtualFolder 节点',
  has('codeblocks.newVirtualFolder', /viewItem == virtualFolder/)
  && has('codeblocks.renameVirtualFolder', /viewItem == virtualFolder/)
  && has('codeblocks.deleteVirtualFolder', /viewItem == virtualFolder/), 'menu', 'ok');
check('右键菜单：工程节点可新建虚拟文件夹', has('codeblocks.newVirtualFolder', /viewItem == project/), 'menu', 'ok');
check('menuStructure：Project tree 子菜单含 Add New Virtual Folder…',
  /Add New Virtual Folder…/.test(menu) && /codeblocks\.newVirtualFolder/.test(menu), 'menu-structure', 'ok');

console.log(`重命名/虚拟文件夹接线回归: ${pass} pass, ${fail} fail`);
process.exit(fail ? 1 : 0);
